import { expect, test } from 'bun:test';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { moneyExactMinor, guestDepositAmountDisplay } from '../frontend/yellow/src/money-exact-minor.mjs';

const NativeNumberFormat=Intl.NumberFormat;
function patch<T>(object:object,key:string,value:unknown,run:()=>T):T {
  const prior=Object.getOwnPropertyDescriptor(object,key);
  Object.defineProperty(object,key,{value,writable:true,configurable:true});
  try{return run();}finally{if(prior)Object.defineProperty(object,key,prior);else Reflect.deleteProperty(object,key);}
}
const locale=<T>(name:string,run:()=>T)=>patch(Intl,'NumberFormat',function(locales: Intl.LocalesArgument, options:Intl.NumberFormatOptions){return new NativeNumberFormat(locales??name,options);},run);
// Immutable independent historical fixture; raw Git b8294182e331e9fbadfd6ba3e9b460dd29f18492:frontend/yellow/src/workspaces/FinanceWorkspace.tsx.
// Finance blob b03d8aead3fc3bc0d3959d3e627704ad72521450; SHA256 7219d737e5960c9175fa75da0d1dc9afed95aafe6b13b1b5e3e57cd77b740179; prior formatter SHA256 5d18e50200579dfb363e595a5df56e7ac691348649f29a0ffc1d96b057e46eaa.
// Embedded bytes preserve the historical comparisons in an ordinary checkout and shallow CI.
const baselineFinanceSource=Buffer.from("",'base64').toString('utf8');
const priorSource="function moneyExactMinor(minor: string, currency: string): string { const formatter = new Intl.NumberFormat(undefined, { style: \"currency\", currency }); const fractionDigits = formatter.resolvedOptions().maximumFractionDigits ?? 2; const amount = BigInt(minor); const negative = amount < 0n; const absolute = negative ? -amount : amount; const scale = 10n ** BigInt(fractionDigits); const whole = absolute / scale; const fraction = (absolute % scale).toString().padStart(fractionDigits, \"0\"); const parts = formatter.formatToParts(negative ? -whole : whole); const rendered = parts.map((part) => part.type === \"fraction\" ? fraction : part.value).join(\"\"); return negative && whole === 0n && !parts.some((part) => part.type === \"minusSign\") ? `-${rendered}` : rendered; }\n";
const priorFormatter=new Function(new Bun.Transpiler({loader:'ts'}).transformSync(priorSource)+';return moneyExactMinor;')() as typeof moneyExactMinor;

test('exact independent magnitudes, differing currency precision and digits beyond int64',()=>locale('en-US',()=>{
  const cases=[['1000','INR','₹10.00'],['0','INR','₹0.00'],['1','INR','₹0.01'],['1001','INR','₹10.01'],['1000','JPY','¥1,000'],['0','JPY','¥0'],['1000','KWD','KWD\u00a01.000'],['1','KWD','KWD\u00a00.001'],['1001','KWD','KWD\u00a01.001'],['9223372036854775807','INR','₹92,233,720,368,547,758.07'],['9223372036854775807','KWD','KWD\u00a09,223,372,036,854,775.807'],['9223372036854775807','JPY','¥9,223,372,036,854,775,807'],['123456789012345678901234567890','INR','₹1,234,567,890,123,456,789,012,345,678.90']];
  for(const [minor,currency,expected] of cases){expect(moneyExactMinor(minor!,currency!)).toBe(expected!);expect(guestDepositAmountDisplay(minor,currency)).toBe(expected!);}
}));

test('Finance extraction preserves independently pinned baseline outputs in three locales',()=>{
  for(const name of ['en-US','de-DE','ar-EG'])locale(name,()=>{
    for(const currency of ['INR','JPY','KWD','XYZ','XAF'])for(const minor of ['0','1','1001','-1','-1001','9223372036854775807','-9223372036854775807'])expect(moneyExactMinor(minor,currency)).toBe(priorFormatter(minor,currency));
    expect(()=>moneyExactMinor('not-money','INR')).toThrow();expect(()=>priorFormatter('not-money','INR')).toThrow();
  });
});

test('guest rejects noncanonical amounts and never coerces supplied metadata',()=>{
  let invoked=0;const hostile={toString(){invoked++;throw Error('coercion');},valueOf(){invoked++;throw Error('coercion');}};
  for(const amount of ['-1','+1','-0','00','01',' 1','1 ','1.0','1e3','',null,undefined,1000,NaN,Infinity,hostile])expect(guestDepositAmountDisplay(amount,'INR')).toBe('Amount unavailable');
  for(const currency of ['inr',' INR','INR ','IN','INRR','<img>',null,undefined,1,hostile])expect(guestDepositAmountDisplay('1000',currency)).toBe('1000 minor units · currency unavailable');
  expect(invoked).toBe(0);
});

test('unknown and nonmonetary codes preserve exact labelled minor units without default precision',()=>{
  for(const currency of ['XYZ','XXX','XTS','XAU','XAG','XPD','XPT','XBA','XBB','XBC','XBD'])expect(guestDepositAmountDisplay('9223372036854775807',currency)).toBe('9223372036854775807 '+currency+' minor units · currency precision unavailable');
  locale('en-US',()=>{for(const currency of ['XCD','XAF','XOF','XPF']){expect(guestDepositAmountDisplay('1000',currency)).toBe(moneyExactMinor('1000',currency));expect(guestDepositAmountDisplay('1000',currency)).not.toContain('unavailable');}});
});

test('missing, throwing or malformed runtime currency metadata fails locally without changing value',()=>{
  const fallback='1000 INR minor units · currency precision unavailable';
  for(const catalogue of [undefined,()=>{throw Error('catalogue');},()=>null,()=>['XYZ']])patch(Intl,'supportedValuesOf',catalogue,()=>expect(guestDepositAmountDisplay('1000','INR')).toBe(fallback));
  patch(Intl,'NumberFormat',function(){throw Error('formatter');},()=>expect(guestDepositAmountDisplay('1000','INR')).toBe(fallback));
  for(const precision of [undefined,null,-1,0.5,NaN,Infinity,'2'])patch(Intl,'NumberFormat',function(){return {resolvedOptions:()=>({maximumFractionDigits:precision})};},()=>expect(guestDepositAmountDisplay('1000','INR')).toBe(fallback));
  patch(globalThis,'Intl',undefined,()=>expect(guestDepositAmountDisplay('1000','INR')).toBe(fallback));
});

test('recognized precision beyond three remains exact rather than clamped',()=>locale('en-US',()=>patch(Intl,'supportedValuesOf',()=>['CLF'],()=>{
  expect(guestDepositAmountDisplay('10001','CLF')).toBe('CLF\u00a01.0001');
  expect(guestDepositAmountDisplay('1','CLF')).toBe('CLF\u00a00.0001');
})));

test('only one production formatter exists and Finance call sites remain unchanged',()=>{
  const current=readFileSync(resolve(import.meta.dir,'../frontend/yellow/src/workspaces/FinanceWorkspace.tsx'),'utf8');
  const base=baselineFinanceSource;
  const expected=base.replace(priorSource,'').replace('import { hostedDepositHandoffPath } from "../hosted-deposit-handoff";','import { hostedDepositHandoffPath } from "../hosted-deposit-handoff";\nimport { moneyExactMinor } from "../money-exact-minor.mjs";');
  expect(current).toBe(expected);
  const shared=readFileSync(resolve(import.meta.dir,'../frontend/yellow/src/money-exact-minor.mjs'),'utf8');
  const exact=priorSource.replace('function moneyExactMinor(minor: string, currency: string): string','export function moneyExactMinor(minor, currency)');
  expect(shared).toContain(exact);expect(shared).not.toMatch(/Number\(.*(?:minor|amount)|parse(?:Float|Int)/);
});
